const video=$('#video'),audio=$('#audio');let room,currentView='room',panelType='',tvPower=true,touring=false,selectedVideo=null,selectedMix=null,trackIndex=0,vinylMode=false,videoURL=null,audioURL=null,loadedVideo=null,lastResumeSave=0,loadingMedia=false;
let movies=read('rewind.movies',[]),mixes=read('rewind.mixes',[]),tracks=read('rewind.tracks',[]);const sessionFiles=new Map();const demo={id:'demo',name:'Midnight Signal',demo:true};
const dbPromise=new Promise(resolve=>{try{const r=indexedDB.open('rewind-room-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);}catch{resolve(null);}});
