function changeView(v,show=true){dismissIntro();currentView=v;touring=false;$('#tour').classList.remove('active');room.setView(v);$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#view-name').textContent=viewNames[v];$('#view-number').textContent=`0${Object.keys(viewNames).indexOf(v)+1} / 07`;if(show){if(v==='tv'||v==='vcr')showPanel('video');else if(v==='stereo')showPanel('audio');else if(v==='toys')showPanel('simon');else closePanel();}}
$$('nav button').forEach(b=>b.onclick=()=>changeView(b.dataset.view));$('#bring-tapes').onclick=()=>{changeView('vcr');importFiles('video');};$('#explore').onclick=()=>{dismissIntro();toast('Try the stereo, a tape, or one of the toys.');};$('#close-panel').onclick=closePanel;function closePanel(){panelType='';$('#panel').classList.add('hidden');}
