// Simon: reproduces the growing sequence, locks input during playback and saves best round.
let simonSeq=[],simonIndex=0,simonBusy=false,simonActive=false,simonToken=0,simonBest=read('rewind.simonBest',0),simonMessage='Watch. Listen. Repeat.';
const simonFreq=[329.63,261.63,220,164.81];const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function flashPad(i,duration=350){room.setSimon(i,true);$(`[data-pad="${i}"]`)?.classList.add('lit');await tone(simonFreq[i],duration/1000,.4,'sine');await wait(duration);room.setSimon(i,false);$(`[data-pad="${i}"]`)?.classList.remove('lit');}
async function simonPlayback(){const token=++simonToken;simonBusy=true;simonMessage='Watch the sequence…';if(panelType==='simon')renderToy('simon');await wait(650);for(let i of simonSeq){if(token!==simonToken)return;await flashPad(i,Math.max(180,420-simonSeq.length*12));await wait(170);}if(token!==simonToken)return;simonBusy=false;simonIndex=0;simonMessage='Your turn.';if(panelType==='simon')renderToy('simon');}
function startSimon(){simonSeq=[Math.floor(Math.random()*4)];simonActive=true;simonPlayback();}
async function pressSimon(i){if(simonBusy)return;if(!simonActive){flashPad(i,220);return;}simonBusy=true;await flashPad(i,230);if(i!==simonSeq[simonIndex]){simonActive=false;simonBusy=false;simonMessage='Almost! Start a new game.';tone(85,.7,.45,'sawtooth');if(panelType==='simon')renderToy('simon');return;}simonIndex++;if(simonIndex===simonSeq.length){simonBest=Math.max(simonBest,simonSeq.length);save('rewind.simonBest',simonBest);simonMessage='Round '+simonSeq.length+' complete.';if(panelType==='simon')renderToy('simon');await wait(650);simonSeq.push(Math.floor(Math.random()*4));simonPlayback();}else simonBusy=false;}
// Speak & Spell: physical keys and keyboard input with browser speech.
const words=['music','planet','window','rocket','yellow','pencil','garden','silver','record','summer','puzzle','picture','blanket','computer','rainbow','cassette','midnight','mountain','electric','tomorrow'];let spellWord='',spellEntry='',spellStatus='Press Start to hear a word.',spellCorrect=0;
function say(text){if(!('speechSynthesis'in window)){toast('Speech is unavailable in this browser.');spellStatus='Spell: '+spellWord.toUpperCase();return;}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.rate=.72;u.pitch=.65;let voices=speechSynthesis.getVoices(),v=voices.find(v=>/en-US/i.test(v.lang));if(v)u.voice=v;speechSynthesis.speak(u);}
function newWord(){spellWord=words[Math.floor(Math.random()*words.length)];spellEntry='';spellStatus='Listen, then spell the word.';room.setSpell('SPELL');say('Spell '+spellWord);if(panelType==='spell')renderToy('spell');}
function checkWord(){if(!spellWord){newWord();return;}if(spellEntry.toLowerCase()===spellWord){spellStatus='Correct! Ready for another?';spellCorrect++;room.setSpell('CORRECT');say('That is correct.');tone(660,.15,.15);spellWord='';}else{spellStatus='Try again. Listen to the word.';room.setSpell('TRY AGAIN');say('Try again. '+spellWord);}if(panelType==='spell')renderToy('spell');}
function spellKey(k){if(k==='▶'){newWord();return;}if(k==='?'){say(spellWord?'Spell '+spellWord:'Press start.');return;}if(k==='↵'){checkWord();return;}if(k==='←')spellEntry=spellEntry.slice(0,-1);else if(/^[a-z]$/i.test(k))spellEntry=(spellEntry+k.toUpperCase()).slice(0,14);room.setSpell(spellEntry||'SPELL');clickSound();let input=$('#spell-input');if(input)input.value=spellEntry;let d=$('.spell-display');if(d)d.textContent=spellEntry||'SPELL';}
function renderToy(type){panelType=type;$('#panel-kicker').textContent=type==='simon'?'SIMON · ELECTRONIC MEMORY':'SPEAK & SPELL · WORD PLAY';$('#panel-title').textContent=type==='simon'?'Just one more round.':'Say it. Spell it.';const tabs=`<div class="toy-tabs"><button data-toy="simon" class="${type==='simon'?'active':''}">Simon</button><button data-toy="spell" class="${type==='spell'?'active':''}">Speak & Spell</button></div>`;if(type==='simon')$('#panel-content').innerHTML=tabs+`<div class="score"><div><strong>${simonSeq.length||'—'}</strong><small>ROUND</small></div><div><strong>${simonBest}</strong><small>PERSONAL BEST</small></div></div><p>${simonMessage}</p><div class="pads">${['Green','Red','Yellow','Blue'].map((c,i)=>`<button data-pad="${i}" aria-label="${c} Simon pad">${c}</button>`).join('')}</div><button class="primary" id="simon-start" style="margin-top:15px">${simonActive?'Restart':'Start game'}</button><p class="subtle">Click the real pads in the room, use these buttons, or press 1–4.</p>`;else $('#panel-content').innerHTML=tabs+`<div class="spell-display">${escapeHTML(spellEntry||'HELLO')}</div><p>${escapeHTML(spellStatus)}</p><input id="spell-input" class="spell-input" type="text" maxlength="14" placeholder="Type the word" autocomplete="off" autocorrect="off" spellcheck="false" value="${escapeHTML(spellEntry)}" aria-label="Your spelling"><div class="row" style="margin-top:12px"><button id="say-word">Hear again</button><button id="check-word">Enter ↵</button></div><button class="primary" id="new-word" style="margin-top:12px">${spellWord?'New word':'Start a word'}</button><p class="subtle">${spellCorrect} correct · Click the toy’s keys or use your keyboard. Voice supplied by your browser.</p>`;
 $$('[data-toy]').forEach(b=>b.onclick=()=>showPanel(b.dataset.toy));if(type==='simon'){$$('[data-pad]').forEach(b=>b.onclick=()=>pressSimon(Number(b.dataset.pad)));$('#simon-start').onclick=startSimon;}else{$('#new-word').onclick=newWord;$('#say-word').onclick=()=>say(spellWord?'Spell '+spellWord:'Press start.');$('#check-word').onclick=checkWord;$('#spell-input').oninput=e=>{spellEntry=e.target.value.replace(/[^a-z]/gi,'').toUpperCase();e.target.value=spellEntry;room.setSpell(spellEntry||'SPELL');$('.spell-display').textContent=spellEntry||'SPELL';};$('#spell-input').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();checkWord();}};}}
function handleAction(action){dismissIntro();if(action.startsWith('view:')){changeView(action.split(':')[1]);clickSound();return;}if(action.startsWith('tape:')){const id=action.slice(5);changeView('vcr');id==='import'?importFiles('video'):loadMovie(id);return;}if(action.startsWith('mix:')){const id=action.slice(4);changeView('stereo');id==='import'?importFiles('audio'):playMix(id);return;}if(action.startsWith('toy:')){changeView('toys',false);showPanel(action.slice(4));return;}if(action.startsWith('simon:')){if(currentView!=='toys'){changeView('toys',false);showPanel('simon');}else pressSimon(Number(action.slice(6)));return;}if(action.startsWith('spell:')){if(currentView!=='toys'){changeView('toys',false);showPanel('spell');}else spellKey(action.slice(6));return;}clickSound();switch(action){case'room:lamp':toggleLamp();break;case'tv:power':tvPower=!tvPower;room.setPower(tvPower);toast(tvPower?'Monitor on.':'Monitor off.');break;case'video:play':if(video.paused||!selectedVideo)toggleVideo();break;case'video:pause':toggleVideo();break;case'video:stop':video.pause();video.currentTime=0;stopDemoSound();if(selectedVideo==='demo')room.setTVMode('standby');updateNow();break;case'video:rew':if(loadedVideo&&loadedVideo!=='demo')video.currentTime=Math.max(0,video.currentTime-10);break;case'video:ff':if(loadedVideo&&loadedVideo!=='demo')video.currentTime=Math.min(video.duration,video.currentTime+10);break;case'video:eject':ejectMovie();break;case'video:tracking':room.setTracking(.8);setTimeout(()=>room.setTracking(0),1200);toast('Tracking adjusted.');break;case'audio:toggle':toggleAudio();break;case'audio:stop':audio.pause();audio.currentTime=0;break;case'audio:prev':advanceAudio(-1);break;case'audio:next':advanceAudio(1);break;case'audio:vinyl':vinylMode=true;changeView('stereo');toggleAudio();break;}}
window.addEventListener('keydown',e=>{if($('#preferences').open)return;if(e.key==='Escape'){changeView('room');return;}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(panelType==='simon'&&/^[1-4]$/.test(e.key)){e.preventDefault();pressSimon(Number(e.key)-1);return;}if(panelType==='spell'){if(/^[a-z]$/i.test(e.key)){spellKey(e.key);return;}if(e.key==='Backspace'){e.preventDefault();spellKey('←');return;}if(e.key==='Enter'){checkWord();return;}}if(e.code==='Space'){e.preventDefault();if(!audio.paused||currentView==='stereo')toggleAudio();else toggleVideo();}});
